using Kernel = CGAL::Exact_predicates_exact_constructions_kernel;
using Point_2 = Kernel::Point_2;
using Polygon_2 = CGAL::Polygon_2<Kernel>;
using Polygon_with_holes_2 = CGAL::Polygon_with_holes_2<Kernel>;
using Nef_polyhedron = CGAL::Nef_polyhedron_2<Kernel>;

std::vector<Point_2> pts1, pts2;
for (const auto& p : P1) pts1.emplace_back(p.x(), p.y());
for (const auto& p : P2) pts2.emplace_back(p.x(), p.y());

Polygon_2 poly1(pts1.begin(), pts1.end());
Polygon_2 poly2(pts2.begin(), pts2.end());

Nef_polyhedron nef1(poly1);
Nef_polyhedron nef2(poly2);
Nef_polyhedron result = nef1.join(nef2);

std::list<Polygon_with_holes_2> polyholes;
result.convert_to_polygon_with_holes(std::back_inserter(polyholes));

std::vector<PolygonWithHoles2d> output;
for (const auto& ph : polyholes) {
    PolygonWithHoles2d pwh;
    Polygon2d outer;
    for (auto it = ph.outer_boundary().vertices_begin(); it != ph.outer_boundary().vertices_end(); ++it) {
        outer.emplace_back(CGAL::to_double(it->x()), CGAL::to_double(it->y()));
    }
    pwh.outer = std::move(outer);
    for (auto hit = ph.holes_begin(); hit != ph.holes_end(); ++hit) {
        Polygon2d hole;
        for (auto it = hit->vertices_begin(); it != hit->vertices_end(); ++it) {
            hole.emplace_back(CGAL::to_double(it->x()), CGAL::to_double(it->y()));
        }
        pwh.holes.emplace_back(std::move(hole));
    }
    output.emplace_back(std::move(pwh));
}
return output;
// END_CODE

